SysDataModelXML.SQLNew:
--LINKEXECOUTPUT DECLARE @FCY VARCHAR(10)='{0}'; DECLARE @RPTSTA INT = 1; DECLARE @RPTMSG NVARCHAR(300) = ''; DECLARE @CanInsert BIT = 1; -- 新增标志变量
-- 仅保留电池序列号重复校验 IF EXISTS(SELECT 1 FROM XWSMKI WHERE XTXT_0 = '#电池序列号#' AND MFGFCY_0 = @FCY AND '#电池序列号#' <> '') BEGIN SET @CanInsert = 0; SET @RPTSTA = 0; SET @RPTMSG = N'LINKPREVENT:lang:{zh:电池序列号重复,请检查,en:Battery serial number duplicate, please check,de:Batterie-Seriennummer doppelt, bitte prüfen}'; END IF EXISTS(SELECT 1 FROM STOCK WHERE STOFLD1_0 = '#电池序列号#' AND STOFCY_0 = @FCY AND '#电池序列号#' <> '') BEGIN SET @CanInsert = 0; SET @RPTSTA = 0; SET @RPTMSG = N'LINKPREVENT:lang:{zh:电池序列号已入库,请检查,en:Battery serial number duplicate, please check,de:Batterie-Seriennummer doppelt, bitte prüfen}'; END
-- 只有当检查通过时才执行插入 IF @CanInsert = 1 BEGIN INSERT INTO XWSMKI ( MACHINEID_0, USERID_0, CUSERID_0, VCRTYP_0, PK_0, BATCHID_0, PKORI_0, CREDATIM_0, STAT_0, SUBDATIM_0, RPFLG_0, RPNUM_0, RPLIN_0, RPNOTE_0, RPDATE_0, RPDATIM_0, MFGFCY_0, MFGNUM_0, ITMREF_0, UOMCPLQTY_0, UOM_0, UOMSTUCOE_0, MFGTRKNUM_0, PCU_0, QTYPCU_0, PCUSTUCOE_0, LOC_0, STA_0, LOT_0, SLO_0, PALNUM_0, CTRNUM_0, SHLDAT_0, XCREUSR_0, VCRLIN_0, YUOMCPLQTY_0, UOMCPLQTY2_0, YUOMCPLQTY2_0, UOM2_0, BPSLOT_0, CREDATTIM_0, UPDDATTIM_0, AUUID_0, CREUSR_0, UPDUSR_0, WRH_0, XTXT_0, XTXT_1, XTXT_2, XDCB_0, XDCB_1, XDCB_2, XDAT_0, XDAT_1, XDAT_2, SERNUM_0, XRMK1_0, XRMK2_0, XRMK3_0, XRMK4_0 ) SELECT '#LOGIN_ID#' AS MACHINEID_0, '#LOGIN_USER#' AS USERID_0, '' AS CUSERID_0, 15 AS VCRTYP_0, '#LINKID_ACTION#' AS PK_0, '#LINKID_ACTION#' AS BATCHID_0, ' ' AS PKORI_0, GETDATE() AS CREDATIM_0, 1 AS STAT_0, '1900-01-01' AS SUBDATIM_0, 1 AS RPFLG_0, ' ' AS RPNUM_0, 0 AS RPLIN_0, ' ' AS RPNOTE_0, '1900-01-01' AS RPDATE_0, '1900-01-01' AS RPDATIM_0, O.MFGFCY_0 AS MFGFCY_0, O.MFGNUM_0 AS MFGNUM_0, O.ITMREF_0 AS ITMREF_0, 0#入库数量# AS UOMCPLQTY_0, ITM.STU_0 AS UOM_0, 1 AS UOMSTUCOE_0, ' ' AS MFGTRKNUM_0, ITM.STU_0 AS PCU_0, #入库数量# QTYPCU_0, 1 AS PCUSTUCOE_0, '#库位#' AS LOC_0, '#存货状态#' AS STA_0, '' AS LOT_0, ' ' AS SLO_0, '' AS PALNUM_0, '' AS CTRNUM_0, GETDATE() AS SHLDAT_0, '', O.MFGLIN_0, 0, 0, 0, 0, 0, GETDATE(), GETDATE(), NEWID(), LEFT('#LOGIN_USER#', 5), ' ', ISNULL((SELECT WRH_0 FROM STOLOC WHERE LOC_0 = '#入库库位#' AND O.MFGFCY_0 = STOFCY_0), ''), '#电池序列号#' AS XTXT_0, '#电机序列号#' AS XTXT_1, '#半成品序列号#' AS XTXT_2, 0, 0, 0, '1900-01-01', '1900-01-01', '1900-01-01', '#车架序列号#', '', '', '', '' FROM MFGITM O INNER JOIN MFGHEAD H ON H.MFGNUM_0 = O.MFGNUM_0 LEFT JOIN ITMMASTER ITM ON ITM.ITMREF_0 = O.ITMREF_0 LEFT JOIN ITMFACILIT ITF ON ITF.ITMREF_0 = O.ITMREF_0 AND ITF.STOFCY_0 = O.MFGFCY_0 WHERE O.MFGNUM_0 = '#工单编号#' AND O.ITMREF_0 = '#产品编码#';
-- 如果插入成功且之前没有错误，设置成功消息 IF @RPTSTA = 1 BEGIN SET @RPTMSG = N'lang:{zh:操作成功,en:Operation successful,de:Vorgang erfolgreich}'; END END
SELECT @RPTSTA AS RPTSTA, @RPTMSG AS RPTMSG;

