scan_para=function(id, r){
  if(id=="linkinput"){
    scan_impl(id, "#"+r+"#");}
  else{
   document.getElementById(id).value=r;
    }
};

//删除后自动刷新
afterFunction=function(id){ 
    if(id=="linkquick12")
    reloadModelData()
}

//扫描状态正常直接查询，不正常跳框提示
scanAfterAction = function (id) {
    if ($("#数据检查").val() !== "") {
        alert($("#数据检查").val());
    keep_focus("linkinput");
        return;
    }
    keep_focus("linkinput");
};
